script:
html { scroll-behavior: smooth; }
::selection { background: var(--e7a94b53-2d18-4f60-a927-8b5e3d1c4002, #191713); color: var(--e7a94b53-2d18-4f60-a927-8b5e3d1c4001, #FBFAF8); }
body { -webkit-font-smoothing: antialiased; }

.wv-link { transition: color 0.18s ease; }
.wv-link:hover { color: var(--e7a94b53-2d18-4f60-a927-8b5e3d1c4006, #B95C38); }

img { filter: saturate(0.95); }
@media (prefers-color-scheme: dark) { img { filter: saturate(0.9) brightness(0.88); } }

a:focus-visible { border-radius: 4px; outline: 2px solid var(--e7a94b53-2d18-4f60-a927-8b5e3d1c4006, #B95C38); outline-offset: 3px; }
